import"./chunk-ZW5NV4UO.js";var e={en:{title:"Retrocomputing on Mastodon: people and tags to follow",description:"Build a Mastodon feed of vintage computers, restoration, emulation and software preservation. Find people and hashtags, then preview their posts.",heading:"Retrocomputing on Mastodon",listTitle:"Retrocomputing",intro:["An Amiga repair, a new Apple II program or a rescued workstation: find people keeping old computers useful and sharing how they work. Vintage hardware, historical software and the communities around them belong here.","Choose people and hashtags, then preview their public posts. Useful subject tags remain available even with no posts, so you can follow and help grow the conversations you care about."],faq:[{q:"Do I need an account?",a:"You can browse and preview public posts without an account. Sign in with your Mastodon account to follow people and hashtags or create a list."},{q:"Does this include emulation and retro games?",a:"Yes, when they connect to vintage computers, programming or preservation. Repairs, old operating systems, BBS communities and hardware recreations also belong here. General gaming nostalgia is outside this selection. Preview tags that contain ads or unrelated posts before following."},{q:"How do I get onto this list?",a:"Share retrocomputing posts regularly and allow your server to suggest your profile. Recent activity, sustained topic fit and review determine the selection. For help or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"Retrocomputing auf Mastodon: Menschen und Hashtags",description:"Entdecke alte Computer, Reparaturen, Emulation und Softwaregeschichte auf Mastodon. Stell deinen Feed zusammen und schau dir die Beitr\xE4ge in der Vorschau an.",heading:"Retrocomputing auf Mastodon",listTitle:"Retrocomputing",intro:["Ein reparierter Amiga, ein neues Programm f\xFCr den Apple II oder eine gerettete Workstation: Hier findest du Menschen, die alte Computer weiter nutzen und ihr Wissen teilen. Historische Hardware und Software stehen im Mittelpunkt.","W\xE4hle Menschen und Hashtags aus und schau dir ihre \xF6ffentlichen Beitr\xE4ge an. Passende Hashtags bleiben auch ohne Beitr\xE4ge dabei. Indem du ihnen folgst und sie verwendest, hilfst du der Community zu wachsen."],faq:[{q:"Brauche ich ein Konto?",a:"Zum St\xF6bern und f\xFCr die Vorschau \xF6ffentlicher Beitr\xE4ge brauchst du kein Konto. Um Menschen und Hashtags zu folgen oder eine Liste anzulegen, meldest du dich mit deinem Mastodon-Konto an."},{q:"Geh\xF6ren Emulation und alte Spiele dazu?",a:"Ja, mit Bezug zu alten Computern, Programmierung oder Erhaltung. Reparaturen, historische Betriebssysteme, Mailboxen und Hardware-Nachbauten geh\xF6ren ebenfalls dazu. Allgemeine Gaming-Nostalgie ist nicht das Thema. Manche Hashtags enthalten Werbung oder fremde Themen; nutze die Vorschau zur Auswahl."},{q:"Wie komme ich auf diese Liste?",a:"Schreib regelm\xE4\xDFig \xFCber Retrocomputing und erlaube deinem Server, dein Profil vorzuschlagen. Aktuelle Aktivit\xE4t, dauerhafter Themenbezug und die Pr\xFCfung z\xE4hlen. Bei Fragen oder f\xFCr eine Entfernung erreichst du @mawkingbird@mastodon.social."}]},fr:{title:"R\xE9troinformatique sur Mastodon : qui suivre",description:"Compose ton fil autour des ordinateurs anciens, de leur restauration et de la pr\xE9servation des logiciels. D\xE9couvre des comptes et essaie les hashtags.",heading:"La r\xE9troinformatique sur Mastodon",listTitle:"R\xE9troinformatique",intro:["Un Amiga r\xE9par\xE9, un nouveau programme pour Apple II ou une station de travail sauv\xE9e : d\xE9couvre des personnes qui font vivre les ordinateurs anciens et partagent leurs connaissances. Le mat\xE9riel et les logiciels historiques sont au c\u0153ur de cette s\xE9lection.","Choisis des comptes et des hashtags, puis explore leurs publications publiques dans l\u2019aper\xE7u. Les tags utiles restent propos\xE9s m\xEAme sans publications, pour que tu puisses suivre et faire grandir les \xE9changes qui t\u2019int\xE9ressent."],faq:[{q:"Faut-il un compte ?",a:"Tu peux parcourir la s\xE9lection et lire les publications publiques sans compte. Connecte-toi avec ton compte Mastodon pour suivre des personnes et des hashtags ou cr\xE9er une liste."},{q:"L\u2019\xE9mulation et les jeux anciens sont-ils inclus ?",a:"Oui, quand ils concernent les ordinateurs anciens, la programmation ou la pr\xE9servation. R\xE9parations, syst\xE8mes historiques, BBS et recr\xE9ations mat\xE9rielles ont aussi leur place. La nostalgie du jeu vid\xE9o en g\xE9n\xE9ral est hors sujet. L\u2019aper\xE7u aide \xE0 rep\xE9rer la publicit\xE9 et les publications sans rapport."},{q:"Comment appara\xEEtre sur cette liste ?",a:"Publie r\xE9guli\xE8rement sur la r\xE9troinformatique et autorise ton serveur \xE0 sugg\xE9rer ton profil. L\u2019activit\xE9 r\xE9cente, la r\xE9gularit\xE9 du sujet et la v\xE9rification comptent aussi. Pour une question ou un retrait, contacte @mawkingbird@mastodon.social."}]},es:{title:"Retroinform\xE1tica en Mastodon: personas y etiquetas",description:"Crea un feed sobre ordenadores cl\xE1sicos, restauraci\xF3n, emulaci\xF3n y preservaci\xF3n de software. Descubre cuentas y etiquetas y prueba la vista previa.",heading:"Retroinform\xE1tica en Mastodon",listTitle:"Retroinform\xE1tica",intro:["Un Amiga reparado, un programa nuevo para Apple II o una estaci\xF3n de trabajo rescatada: encuentra a quienes mantienen vivos los ordenadores cl\xE1sicos y comparten lo que aprenden. Aqu\xED importan tanto el hardware como el software hist\xF3rico.","Elige personas y etiquetas y explora sus publicaciones p\xFAblicas. Las etiquetas \xFAtiles siguen disponibles aunque no tengan publicaciones, para que puedas seguirlas y ayudar a crear comunidad."],faq:[{q:"\xBFNecesito una cuenta?",a:"Puedes explorar la selecci\xF3n y ver publicaciones p\xFAblicas sin cuenta. Inicia sesi\xF3n con tu cuenta de Mastodon para seguir personas y etiquetas o crear una lista."},{q:"\xBFIncluye emulaci\xF3n y juegos antiguos?",a:"S\xED, cuando est\xE1n relacionados con ordenadores cl\xE1sicos, programaci\xF3n o preservaci\xF3n. Tambi\xE9n caben reparaciones, sistemas operativos hist\xF3ricos, BBS y recreaciones de hardware. La nostalgia general por los videojuegos queda fuera. Usa la vista previa para detectar anuncios o publicaciones que no te interesen."},{q:"\xBFC\xF3mo puedo aparecer en esta lista?",a:"Publica con regularidad sobre retroinform\xE1tica y permite que tu servidor recomiende tu perfil. La actividad reciente, la continuidad del tema y la revisi\xF3n determinan la selecci\xF3n. Para consultas o retiradas, contacta con @mawkingbird@mastodon.social."}]}};export{e as COPY};
